import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"调试（入口页）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/debugging.md","filePath":"zh/dev/debugging.md"}'),s={name:"zh/dev/debugging.md"};function c(l,e,n,r,i,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="调试-入口页" tabindex="-1">调试（入口页） <a class="header-anchor" href="#调试-入口页" aria-label="Permalink to &quot;调试（入口页）&quot;">​</a></h1><p>简短的导览。完整的汇编 —— 串口取证、klog 环形缓冲区、 崩溃转储与寄存器快照、静默失败方法论，以及故障注入工具 —— 现在位于 <a href="./debug-handbook.html">debug-handbook.md</a>；测试程序与 隐藏开关的清单位于 <a href="./debug-interfaces.html">debug-interfaces.md</a>。本页保留日常 必备要点并指引后续阅读。</p><h2 id="先读启动日志" tabindex="-1">先读启动日志 <a class="header-anchor" href="#先读启动日志" aria-label="Permalink to &quot;先读启动日志&quot;">​</a></h2><p>每个子系统在启动时都会打印一行 <code>.... OK</code>。最后一条 没有打印的行就是出故障的子系统。捕获它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none</span></span></code></pre></div><h2 id="客户机内工具" tabindex="-1">客户机内工具 <a class="header-anchor" href="#客户机内工具" aria-label="Permalink to &quot;客户机内工具&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dmesg            (kernel ring replay; dmesg N for more lines)</span></span>
<span class="line"><span>ush&gt; logcat -f        (live follow of the kernel log)</span></span>
<span class="line"><span>ush&gt; logctl status    (levels, filters, file state)</span></span>
<span class="line"><span>ush&gt; health           (CPU/mem/tasks/IO + the three alarm bits)</span></span>
<span class="line"><span>ush&gt; exc              (exception self-test - proves the trap path)</span></span>
<span class="line"><span>ush&gt; crashlog         (past crash records)</span></span>
<span class="line"><span>ush&gt; dumpinfo         (core dump status)</span></span>
<span class="line"><span>ush&gt; crashtest dump   (capture a dump WITHOUT panicking - wiring check)</span></span></code></pre></div><p>各处的行格式统一为：<code>[SSS.mmm] LEVEL module: message</code>。</p><h2 id="panic-路径" tabindex="-1">panic 路径 <a class="header-anchor" href="#panic-路径" aria-label="Permalink to &quot;panic 路径&quot;">​</a></h2><p>内核 panic 会把异常帧（寄存器 + 故障地址 + 回溯）转储到 串口并写入 crashlog 环形缓冲区；挂载了文件系统时， <code>/var/crash/core.dump</code> 携带 OCDUMP01 镜像。<code>crashtest</code> 触发一次刻意制造的 panic —— 在真正需要之前， 用它验证你的捕获接线是否可用。每类异常下各寄存器的含义： <a href="./debug-handbook.html">debug-handbook.md</a> 第 3 节。</p><h2 id="没有报错但也不工作" tabindex="-1">没有报错但也不工作？ <a class="header-anchor" href="#没有报错但也不工作" aria-label="Permalink to &quot;没有报错但也不工作？&quot;">​</a></h2><p>沿静默失败阶梯排查：健康告警 -&gt; 日志<em>环形缓冲区</em> （不是实时控制台）-&gt; kcap 捕获陷阱（被捕获的 op 会吞掉 实时输出 —— 检查路由方式）-&gt; 返回值约定（L1SVC 调用只要 路由成功就&quot;成功&quot;；失败文本位于 <code>out</code> 之内）-&gt; 识别诚实跳过 字符串。完整方法论：<a href="./debug-handbook.html">debug-handbook.md</a> 第 4 节。</p><h2 id="在宿主侧调试内核" tabindex="-1">在宿主侧调试内核 <a class="header-anchor" href="#在宿主侧调试内核" aria-label="Permalink to &quot;在宿主侧调试内核&quot;">​</a></h2><ul><li>调试符号：流水线以 <code>-g</code> 链接，然后 strip 最终 ELF； <code>build/opencube_base.elf</code>（<code>strip</code> 之前、<code>make kernel</code> 期间产出）是你的符号载体。</li><li>在 QEMU 中：<code>-d int,cpu_reset -D qemu.log</code> 记录中断与 复位；<code>-s -S</code> 加 gdb（<code>target remote localhost:1234</code>） 提供经典的远程调试循环。</li><li>可重现构建意味着两次复现的崩溃是<em>完全相同的字节</em> —— 多次尝试之间不存在海森堡式构建差异 （<code>make reproducible-check</code>）。</li></ul><h2 id="宿主单元测试" tabindex="-1">宿主单元测试 <a class="header-anchor" href="#宿主单元测试" aria-label="Permalink to &quot;宿主单元测试&quot;">​</a></h2><p><code>make test</code> 针对 real 内核源码编译并运行 <code>tests/host_*.c</code> 下的测试套件（加密向量、tar、gzip、字符串、FAT 结构、 MB2 解析，宿主编译器上开 ASAN）。这里的一次回归比 一次启动循环的迭代快得多。清单：<a href="./host-tests.html">host-tests.md</a>。</p><h2 id="已知的锋利边缘-来自审计记录" tabindex="-1">已知的锋利边缘（来自审计记录） <a class="header-anchor" href="#已知的锋利边缘-来自审计记录" aria-label="Permalink to &quot;已知的锋利边缘（来自审计记录）&quot;">​</a></h2><ul><li>4 GiB 以上的 xHCI DMA 会在探测和每次传输时被拒绝 —— 如果 xHCI 设备消失，检查你的 QEMU 内存大小。</li><li>ATA-DMA 对齐依赖堆的 32 字节块头；如果你改动 <code>mem_heap.c</code>，运行 <code>fstest</code> + 一个 FAT32 挂载测试。</li><li>multiboot2 解析器校验 tag 尺寸；测试中&quot;手工拼造&quot;的 mbi 必须遵守每个 tag 的最小值，否则解析会提前停止。</li><li>QEMU 在 HMP 截屏之后会立刻丢弃串口 RX 字节 —— 功能测试轮次从不截图 （<a href="./qemu-testing.html">qemu-testing.md</a> 第 4 节）。</li><li>被捕获的 L1SVC op 在运行期间会同时压制帧缓冲和串口 tee —— 停驻或占用实时会话的 op 必须直连路由 （kcap 陷阱，<a href="./debug-handbook.html">debug-handbook.md</a> 4.3）。</li><li><code>#DF</code> panic 是刻意最小化的（一条静态串口行， 无记录/转储/刷写）—— 不要指望双重故障会产生转储。</li></ul><h2 id="症状-第一步-速查" tabindex="-1">症状 -&gt; 第一步（速查） <a class="header-anchor" href="#症状-第一步-速查" aria-label="Permalink to &quot;症状 -&gt; 第一步（速查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>第一步</th><th>原因</th></tr></thead><tbody><tr><td>启动在阶梯中途停止</td><td>读串口启动日志；最后缺失的 <code>OK</code> 行 = 出故障的子系统</td><td>每个子系统在启动时打印一行 <code>.... OK</code></td></tr><tr><td>机器挂死、控制台无响应</td><td>是否 <code>/HANGAT</code> 之类？复位后检查看门狗状态 + <code>crashlog</code></td><td>15 秒软看门狗 + 6300ESB 继电器产出的是证据，不是沉默</td></tr><tr><td>内核 panic</td><td>抄下串口横幅 + 寄存器转储；重启后 <code>crashlog</code>/<code>dumpinfo</code></td><td>OCDUMP01 镜像 + 32 槽位环形缓冲区会留存</td></tr><tr><td>用户程序行为异常</td><td>用 <code>run &lt;name&gt;</code> 运行它；前后各 <code>ps</code> 一次；检查 <code>exc</code></td><td>ring-3 故障是 kill 而不是 panic —— 内核继续运行</td></tr><tr><td>命令&quot;什么都没做&quot;</td><td>检查路由方式 + 返回约定；寻找诚实跳过字符串</td><td>L1SVC 调用只要路由成功就&quot;成功&quot;；失败文本在 <code>out</code> 内</td></tr><tr><td>输出在操作中途消失</td><td>kcap 捕获陷阱</td><td>捕获会压制实时通道</td></tr><tr><td>怀疑存储损坏</td><td><code>fsck &lt;dev&gt;</code>、<code>disk_rw_test &lt;dev&gt;</code>、<code>lsblk</code> 中的缓存统计</td><td>写回缓存只在写回成功后释放脏槽位</td></tr><tr><td>网络停滞</td><td><code>netstat</code>、<code>tcpstats</code>（RTO/cwnd/SACK 状态）、<code>net_rx_bad_checksum</code></td><td>连接表会告诉你哪一层停滞了</td></tr><tr><td>疑似熵/加密问题</td><td><code>cryptotest</code>、<code>dhtest</code></td><td>对 TLS/SSH 所用原语的 NIST 向量门禁</td></tr></tbody></table><h2 id="提交可调试的报告" tabindex="-1">提交可调试的报告 <a class="header-anchor" href="#提交可调试的报告" aria-label="Permalink to &quot;提交可调试的报告&quot;">​</a></h2><p>在报告内核侧问题之前，收集这份清单 —— 每一项都是代码树 已经为你提供的机制：</p><ol><li><strong>构建标识</strong>：<code>uname -a</code> 输出（版本字符串 + OTA 比对 所用的数字构建 id）—— 可重现构建意味着这两个数字 就能锁定精确字节。</li><li><strong>完整串口日志</strong>（<code>-serial file:boot.log</code>），而不是尾部 的截图 —— 启动阶梯最后缺失的 <code>OK</code> 行指出出故障的 子系统。</li><li><strong>klog 环形日志尾部</strong>：<code>dmesg 200</code>（加上 <code>logctl status</code> 以了解过滤器/级别）；注意页脚 <code>-- &lt;shown&gt; lines (ring &lt;count&gt;/1024, dropped &lt;n&gt;) --</code>。</li><li><strong>崩溃证据（若有）</strong>：串口的 panic 横幅 + 寄存器转储， 重启后再取 <code>crashlog</code>（以及 <code>crashlog flush</code>）加上 <code>dumpinfo</code>；挂载了文件系统时取 <code>/var/crash/core.dump</code> 的 OCDUMP01 镜像。</li><li><strong>健康快照</strong>（<code>health</code>）—— 告警行与五个指标区段可以 把常见嫌疑人排除或锁定。</li><li><strong>复现步骤</strong>，在干净的 <code>make run-bios</code> 启动上执行， 并说明你的树上 <code>make reproducible-check</code> 是否通过 （两次复现的崩溃是相同字节）。</li><li>QEMU 场景：精确的命令行（机型很重要 —— TCO 只在 q35 上存在）以及 QEMU 版本。</li></ol><h2 id="下一步去哪" tabindex="-1">下一步去哪 <a class="header-anchor" href="#下一步去哪" aria-label="Permalink to &quot;下一步去哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>页面</th></tr></thead><tbody><tr><td>串口/klog/崩溃证据、寄存器解读、故障注入</td><td><a href="./debug-handbook.html">debug-handbook.md</a></td></tr><tr><td>约 93 个测试程序、诊断深度、隐藏开关</td><td><a href="./debug-interfaces.html">debug-interfaces.md</a></td></tr><tr><td>内部调用路径（execve、L1SVC、RX、块 IO、崩溃、OTA）</td><td><a href="./call-chains.html">call-chains.md</a></td></tr><tr><td>内核结构体及谁在操作它们</td><td><a href="./data-structures.html">data-structures.md</a></td></tr><tr><td>QEMU 勘误、sendkey、OVMF</td><td><a href="./qemu-testing.html">qemu-testing.md</a></td></tr><tr><td>子系统深入（klog、崩溃、健康、看门狗、加密、OTA、OCIRE 嵌入）</td><td><a href="./../internals/">../internals/index.md</a></td></tr></tbody></table>`,25)])])}const g=t(s,[["render",c]]);export{u as __pageData,g as default};
